/**
 * HTTP section of the runtime metadata (`metadata.extensions.http`), generated by the compiler
 * extension `@znight/http/compiler` and consumed by {@link HttpPlugin}. See
 * docs/internals/architecture.md §9.1. Hand-written metadata (tests) must follow the same shape.
 */
import type { Token } from '@znight/core'
import type { HttpContext } from './context.ts'

/** Route methods. `ALL` registers the route for GET, HEAD, POST, PUT, PATCH, DELETE and OPTIONS. */
export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE' | 'HEAD' | 'OPTIONS' | 'ALL'

/** Where a handler parameter comes from. */
export type HttpParamSource = 'param' | 'query' | 'body' | 'headers' | 'request' | 'response' | 'context'

/** A handler parameter (informational: extraction, coercion and validation happen in `invoke`). */
export interface HttpParamDefinition {
  /** Position in the handler signature. */
  readonly index: number
  readonly source: HttpParamSource
  /** Parameter / query key / header name (lower case). Absent: the whole object. */
  readonly name?: string
  /** Serialised declared type (`number`, `string[]`, `'asc' | 'desc'`...). */
  readonly type?: string
  readonly optional?: boolean
  /** `true` when the value is validated with a schema. */
  readonly schema?: boolean
}

/** A route: one decorated method of a controller. */
export interface HttpRouteDefinition {
  readonly method: HttpMethod
  /** Path of the route decorator, normalised (`/:id`). */
  readonly path: string
  /** `joinPaths(controller.basePath, path)` (without the plugin `prefix`). */
  readonly fullPath: string
  /** Name of the handler method. */
  readonly handler: string
  /** `@HttpCode(status)`. */
  readonly status?: number
  /** `@Header(name, value)` entries (names in lower case). */
  readonly headers?: Readonly<Record<string, string>>
  /** Route metadata (`createRouteDecorator`), merged over the controller metadata at runtime. */
  readonly meta: Readonly<Record<string, unknown>>
  /** Route guards (provider tokens), run after global and controller guards. */
  readonly guards: readonly Token[]
  /** Route interceptors (provider tokens), innermost. */
  readonly interceptors: readonly Token[]
  readonly params: readonly HttpParamDefinition[]
  /** `true` when the handler takes `@Res()` and writes the response itself. */
  readonly rawResponse?: boolean
  /**
   * Calls the handler: extracts, coerces and validates every argument from the context, then calls
   * the method on the controller instance. May return a promise.
   */
  // biome-ignore lint/suspicious/noExplicitAny: generated functions take the concrete controller class
  readonly invoke: (controller: any, ctx: HttpContext) => unknown
}

/** A controller: a provider whose methods are routes. */
export interface HttpControllerDefinition {
  /** Provider token of the controller class. */
  readonly token: Token
  /** Normalised base path (`/users`, `/` when absent). */
  readonly basePath: string
  /** Controller guards (provider tokens). */
  readonly guards: readonly Token[]
  /** Controller interceptors (provider tokens). */
  readonly interceptors: readonly Token[]
  /** Controller metadata (`createRouteDecorator` on the class). */
  readonly meta: Readonly<Record<string, unknown>>
  readonly routes: readonly HttpRouteDefinition[]
}

/** `metadata.extensions.http`. */
export interface HttpMetadata {
  readonly controllers: readonly HttpControllerDefinition[]
}

declare module '@znight/core' {
  interface ZnightExtensionsMetadata {
    readonly http?: HttpMetadata
  }
}
